-- Deux thèmes pour la cuisine de restaurant : « Dans la cuisine » et « Cuisiner un plat » (page /themes), avec la traduction du dialogue (zh, ko, pt, es ; non relue, reviewed = 0).
-- Pas de fichier MP3 : la page lit le dialogue avec la voix du navigateur. Peut être exécuté plusieurs fois sans doublons. À lancer avant frenchdb_9_qcm_themes_cuisine.sql.
SET NAMES utf8mb4;

INSERT INTO `themes` (`dialogue_content`, `nom`, `title`, `audio`)
SELECT 'Chef : Bonjour Léa. Aujourd''hui, c''est ton premier jour en cuisine.\r\n\r\nLéa : Bonjour chef. Je suis prête !\r\n\r\nChef : Très bien. D''abord, mets ton tablier et lave-toi les mains.\r\n\r\nLéa : Oui, chef. Où sont les couteaux ?\r\n\r\nChef : Dans le tiroir, à gauche. Prends aussi la planche à découper.\r\n\r\nLéa : Pour les carottes, je prends l''éplucheur ?\r\n\r\nChef : Oui, il est à côté de l''évier. Ensuite, tu coupes les carottes en rondelles.\r\n\r\nLéa : D''accord. Et la grande casserole, elle est où ?\r\n\r\nChef : Sur l''étagère, en haut. La poêle est en bas, sous le plan de travail.\r\n\r\nLéa : Et le fouet ? Et la passoire ?\r\n\r\nChef : Dans le placard, devant toi. Attention, le four est très chaud : prends toujours les maniques !\r\n\r\nLéa : Compris, chef. Je commence par éplucher les carottes.\r\n\r\nChef : Parfait. Et n''oublie pas : après, tu nettoies tout !', 'Dans la cuisine', 'Dans la cuisine', NULL FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `themes` WHERE `nom` = 'Dans la cuisine');

INSERT IGNORE INTO `translations` (`kind`, `entity_id`, `lang`, `content`, `reviewed`)
SELECT 'THEME_DIALOGUE', t.`id`, 'zh', '主厨：你好，Léa。今天是你在厨房的第一天。\n\nLéa：你好，主厨。我准备好了！\n\n主厨：很好。首先，系上围裙，洗手。\n\nLéa：好的，主厨。刀在哪里？\n\n主厨：在左边的抽屉里。还要拿上砧板。\n\nLéa：切胡萝卜，我用削皮器吗？\n\n主厨：对，它在水槽旁边。然后把胡萝卜切成圆片。\n\nLéa：好的。那口大锅在哪里？\n\n主厨：在架子上面，高处。平底锅在下面，工作台下方。\n\nLéa：那打蛋器呢？还有滤网呢？\n\n主厨：在你面前的柜子里。小心，烤箱很烫：一定要戴隔热手套！\n\nLéa：明白了，主厨。我先从削胡萝卜皮开始。\n\n主厨：很好。别忘了：之后要把所有东西都清洗干净！', 0 FROM `themes` t WHERE t.`nom` = 'Dans la cuisine';
INSERT IGNORE INTO `translations` (`kind`, `entity_id`, `lang`, `content`, `reviewed`)
SELECT 'THEME_DIALOGUE', t.`id`, 'ko', '셰프: 안녕, Léa. 오늘은 주방에서 첫 출근하는 날이야.\n\nLéa: 안녕하세요, 셰프님. 준비됐어요!\n\n셰프: 좋아. 먼저 앞치마를 두르고 손을 씻어.\n\nLéa: 네, 셰프님. 칼은 어디 있어요?\n\n셰프: 왼쪽 서랍에 있어. 도마도 가져가.\n\nLéa: 당근은 필러로 깎을까요?\n\n셰프: 응, 필러는 싱크대 옆에 있어. 그다음에 당근을 동그랗게 썰어.\n\nLéa: 알겠어요. 그리고 큰 냄비는 어디 있어요?\n\n셰프: 선반 위쪽에 있어. 프라이팬은 아래, 조리대 밑에 있고.\n\nLéa: 거품기는요? 체는요?\n\n셰프: 네 앞에 있는 찬장에 있어. 조심해, 오븐이 아주 뜨거우니까 항상 오븐 장갑을 껴!\n\nLéa: 알겠습니다, 셰프님. 당근 껍질부터 벗길게요.\n\n셰프: 좋아. 그리고 잊지 마: 끝나면 전부 청소하는 거야!', 0 FROM `themes` t WHERE t.`nom` = 'Dans la cuisine';
INSERT IGNORE INTO `translations` (`kind`, `entity_id`, `lang`, `content`, `reviewed`)
SELECT 'THEME_DIALOGUE', t.`id`, 'pt', 'Chef: Bom dia, Léa. Hoje é o seu primeiro dia na cozinha.\n\nLéa: Bom dia, chef. Estou pronta!\n\nChef: Muito bem. Primeiro, coloque o avental e lave as mãos.\n\nLéa: Sim, chef. Onde estão as facas?\n\nChef: Na gaveta, à esquerda. Pegue também a tábua de cortar.\n\nLéa: Para as cenouras, pego o descascador?\n\nChef: Sim, ele está ao lado da pia. Depois, corte as cenouras em rodelas.\n\nLéa: Certo. E a panela grande, onde está?\n\nChef: Na prateleira, em cima. A frigideira está embaixo, debaixo da bancada.\n\nLéa: E o batedor? E o escorredor?\n\nChef: No armário, na sua frente. Cuidado, o forno está muito quente: use sempre as luvas térmicas!\n\nLéa: Entendi, chef. Começo descascando as cenouras.\n\nChef: Perfeito. E não esqueça: depois, limpe tudo!', 0 FROM `themes` t WHERE t.`nom` = 'Dans la cuisine';
INSERT IGNORE INTO `translations` (`kind`, `entity_id`, `lang`, `content`, `reviewed`)
SELECT 'THEME_DIALOGUE', t.`id`, 'es', 'Chef: Hola, Léa. Hoy es tu primer día en la cocina.\n\nLéa: Hola, chef. ¡Estoy lista!\n\nChef: Muy bien. Primero, ponte el delantal y lávate las manos.\n\nLéa: Sí, chef. ¿Dónde están los cuchillos?\n\nChef: En el cajón, a la izquierda. Coge también la tabla de cortar.\n\nLéa: Para las zanahorias, ¿cojo el pelador?\n\nChef: Sí, está al lado del fregadero. Después, corta las zanahorias en rodajas.\n\nLéa: De acuerdo. ¿Y la olla grande, dónde está?\n\nChef: En la estantería, arriba. La sartén está abajo, debajo de la encimera.\n\nLéa: ¿Y el batidor? ¿Y el colador?\n\nChef: En el armario, delante de ti. Cuidado, el horno está muy caliente: ¡usa siempre las manoplas!\n\nLéa: Entendido, chef. Empiezo pelando las zanahorias.\n\nChef: Perfecto. Y no olvides: ¡después, limpia todo!', 0 FROM `themes` t WHERE t.`nom` = 'Dans la cuisine';

INSERT INTO `themes` (`dialogue_content`, `nom`, `title`, `audio`)
SELECT 'Chef : Léa, table douze : un poulet rôti et une soupe de légumes.\r\n\r\nLéa : Oui, chef ! Je commence par la soupe ?\r\n\r\nChef : Oui. Épluche les pommes de terre et coupe les oignons.\r\n\r\nLéa : Je les fais revenir dans la casserole avec un peu d''huile ?\r\n\r\nChef : Oui. Ensuite, ajoute l''eau et fais bouillir pendant vingt minutes.\r\n\r\nLéa : Je mélange de temps en temps ?\r\n\r\nChef : Exactement. Puis tu goûtes, et tu ajoutes du sel et du poivre.\r\n\r\nLéa : Et le poulet ? Je le mets au four ?\r\n\r\nChef : Oui, à deux cents degrés, pendant quarante minutes. Surveille la cuisson !\r\n\r\nLéa : Chef, le poulet est cuit. Je le sors ?\r\n\r\nChef : Attends : laisse-le reposer cinq minutes, puis coupe-le en tranches.\r\n\r\nLéa : Et pour dresser l''assiette ?\r\n\r\nChef : Un peu de purée, deux tranches de poulet, et la sauce autour.\r\n\r\nLéa : Voilà, chef. C''est prêt !\r\n\r\nChef : Bravo ! Table douze, départ !', 'Cuisiner', 'Cuisiner un plat', NULL FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `themes` WHERE `nom` = 'Cuisiner');

INSERT IGNORE INTO `translations` (`kind`, `entity_id`, `lang`, `content`, `reviewed`)
SELECT 'THEME_DIALOGUE', t.`id`, 'zh', '主厨：Léa，十二号桌：一份烤鸡和一份蔬菜汤。\n\nLéa：好的，主厨！我先做汤吗？\n\n主厨：对。把土豆削皮，把洋葱切好。\n\nLéa：我放一点油，在锅里把它们炒香吗？\n\n主厨：对。然后加水，煮沸二十分钟。\n\nLéa：我要时不时搅拌一下吗？\n\n主厨：没错。然后尝一下味道，再加盐和胡椒。\n\nLéa：那鸡肉呢？我把它放进烤箱吗？\n\n主厨：对，两百度，烤四十分钟。注意火候！\n\nLéa：主厨，鸡肉熟了。我把它拿出来吗？\n\n主厨：等一下：让它静置五分钟，然后切成片。\n\nLéa：那摆盘怎么做？\n\n主厨：放一点土豆泥，两片鸡肉，酱汁淋在周围。\n\nLéa：好了，主厨。准备好了！\n\n主厨：做得好！十二号桌，出餐！', 0 FROM `themes` t WHERE t.`nom` = 'Cuisiner';
INSERT IGNORE INTO `translations` (`kind`, `entity_id`, `lang`, `content`, `reviewed`)
SELECT 'THEME_DIALOGUE', t.`id`, 'ko', '셰프: Léa, 12번 테이블이야. 로스트 치킨 하나랑 채소 수프 하나.\n\nLéa: 네, 셰프님! 수프부터 시작할까요?\n\n셰프: 응. 감자 껍질을 벗기고 양파를 썰어.\n\nLéa: 기름을 조금 두르고 냄비에서 볶을까요?\n\n셰프: 그래. 그다음에 물을 넣고 20분 동안 끓여.\n\nLéa: 가끔씩 저어 줄까요?\n\n셰프: 맞아. 그다음에 맛을 보고 소금과 후추를 넣어.\n\nLéa: 닭고기는요? 오븐에 넣을까요?\n\n셰프: 응, 200도에서 40분 동안. 익는 걸 잘 지켜봐!\n\nLéa: 셰프님, 닭고기가 다 익었어요. 꺼낼까요?\n\n셰프: 잠깐: 5분 동안 그대로 두었다가 얇게 썰어.\n\nLéa: 접시는 어떻게 담을까요?\n\n셰프: 으깬 감자를 조금, 닭고기 두 조각, 소스는 주변에.\n\nLéa: 다 됐어요, 셰프님. 준비됐습니다!\n\n셰프: 잘했어! 12번 테이블, 나갑니다!', 0 FROM `themes` t WHERE t.`nom` = 'Cuisiner';
INSERT IGNORE INTO `translations` (`kind`, `entity_id`, `lang`, `content`, `reviewed`)
SELECT 'THEME_DIALOGUE', t.`id`, 'pt', 'Chef: Léa, mesa doze: um frango assado e uma sopa de legumes.\n\nLéa: Sim, chef! Começo pela sopa?\n\nChef: Sim. Descasque as batatas e corte as cebolas.\n\nLéa: Eu refogo na panela com um pouco de óleo?\n\nChef: Sim. Depois, adicione a água e deixe ferver por vinte minutos.\n\nLéa: Eu mexo de vez em quando?\n\nChef: Exatamente. Depois você prova e adiciona sal e pimenta.\n\nLéa: E o frango? Coloco no forno?\n\nChef: Sim, a duzentos graus, por quarenta minutos. Vigie o cozimento!\n\nLéa: Chef, o frango está pronto. Eu tiro do forno?\n\nChef: Espere: deixe descansar cinco minutos e depois corte em fatias.\n\nLéa: E para empratar?\n\nChef: Um pouco de purê, duas fatias de frango e o molho em volta.\n\nLéa: Pronto, chef. Está tudo pronto!\n\nChef: Parabéns! Mesa doze, saindo!', 0 FROM `themes` t WHERE t.`nom` = 'Cuisiner';
INSERT IGNORE INTO `translations` (`kind`, `entity_id`, `lang`, `content`, `reviewed`)
SELECT 'THEME_DIALOGUE', t.`id`, 'es', 'Chef: Léa, mesa doce: un pollo asado y una sopa de verduras.\n\nLéa: ¡Sí, chef! ¿Empiezo por la sopa?\n\nChef: Sí. Pela las patatas y corta las cebollas.\n\nLéa: ¿Las sofrío en la olla con un poco de aceite?\n\nChef: Sí. Luego añade el agua y hierve durante veinte minutos.\n\nLéa: ¿Remuevo de vez en cuando?\n\nChef: Exacto. Después pruebas y añades sal y pimienta.\n\nLéa: ¿Y el pollo? ¿Lo meto en el horno?\n\nChef: Sí, a doscientos grados, durante cuarenta minutos. ¡Vigila la cocción!\n\nLéa: Chef, el pollo está hecho. ¿Lo saco?\n\nChef: Espera: déjalo reposar cinco minutos y luego córtalo en lonchas.\n\nLéa: ¿Y para emplatar?\n\nChef: Un poco de puré, dos lonchas de pollo y la salsa alrededor.\n\nLéa: Listo, chef. ¡Ya está!\n\nChef: ¡Bravo! ¡Mesa doce, sale!', 0 FROM `themes` t WHERE t.`nom` = 'Cuisiner';
